\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22\cf1 91\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 -94\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs22\chcbpat17\cf1 Caeremoniae secundum consuetudinem Sacri Specus}}\plain \f1\lang1033\fs22\cf1  \u8250 \'9b\plain \f1\i\lang1033\fs22\cf1 Incipiunt ceremonie secundum consuetudinem monasterii Sacri Specus et primo de discoopercionibus plenis\plain \f1\lang1033\fs22\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs22\cf1 Primo ad omne Deus in adiutorium in principio horarum usque ad Sicut erat\plain \f1\lang1033\fs22\cf1  \u8230 \'85 Sehr stark verk\u252 \'fcrzende Ausz\u252 \'fcge, nur wenig \u220 \'dcbereinstimmungen mit der Ed. \plain \f1\scaps\lang1033\fs22\cf1 Angerer\plain \f1\lang1033\fs22\cf1  CCM 1, S.\plain \f2\lang1032\fs22\cf1  34-40. \u8213 \'af \plain \f1\lang1033\fs22\cf1 95\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1   leer.}

