\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 108\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 -109\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs22\chcbpat17 Excerpta de arte punctandi}}\plain \f1\lang1033\fs22  \u8250 \'9b\plain \f1\i\lang1033\fs22 Perotus. Suspensivus sive virgula\u8249 \'8b\plain \f1\lang1033\fs22  \plain \f1\i\lang1033\fs22 est simplex virgula que solet quietis gratia poni antequam sensus aliquis clausule haberi possit hoc modo \u8230 \'85\plain \f1\lang1033\fs22 , \u8250 \'9b\plain \f1\i\lang1033\fs22 Brictius\u8249 \'8b\plain \f1\lang1033\fs22  \plain \f1\i\lang1033\fs22 Subiecti distinctio est oracio imperfecta in qua nec constructio nec sentencia est perfecta \plain \f1\lang1033\fs22 \u8230 \'85, (109\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 )\plain \f1\super\lang1033\fs24  \plain \f1\lang1033\fs22 \u8250 \'9b\plain \f1\i\lang1033\fs22 De modo punctandi ex Mar\plain \f3\lang1024\fs22 [\plain \f1\lang1033\fs22 garita\plain \f3\lang1024\fs22 ]\plain \f1\i\lang1033\fs22  Po\plain \f3\lang1024\fs22 [\plain \f1\lang1033\fs22 etica\plain \f3\lang1024\fs22 ]\plain \f1\lang1033\fs22 \u8249 \'8b \plain \f1\i\lang1033\fs22 Generales punctandi species apud modernos sunt octo videlicet virgula recta \plain \f1\lang1033\fs22 \u8230 \'85-\u8230 \'85 \plain \f1\i\lang1033\fs22 abbatem nostrum summo dolore confici.\plain \f1\lang1033\fs22  \plain \f2\lang1032\fs22 \u8213 \'af \plain \f1\lang1033\fs22 Ausz\u252 \'fcge u.a. aus: Nicolaus Perottus, Rudimenta grammatices (Druck: \plain \f1\scaps\lang1033\fs22 Hain \plain \f1\lang1033\fs22 12680).}

