\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22\cf1 Der Verfasser der Schrift (pater Hieronymus eremita) ist nicht n\u228 \'e4her zu identifizieren. Bei dem Widmungsempf\u228 \'e4nger handelt es sich wohl um {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17\cf1 Leonhard I.}}\plain \f1\lang1033\fs22\cf1  aus der Augsburger Kaufmannsfamilie Sulzer, der 1508-1512 als Konsul im Fondaco dei Tedeschi in Venedig amtierte (Augsburger Eliten S. 831; zur Familie: Augsburger Stadtlexikon S. 864 f). Nach dem Besitzvermerk 20\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1  war die Hs 1562 im Besitz des Augsburger Kaufmanns {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100gi/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17\cf1 Philipp Reihing}}\plain \f1\lang1033\fs22\cf1  (\u8224 \'86 1593), der ebenfalls Gesch\u228 \'e4ftsbeziehungen nach Oberitalien unterhielt (Augsburger Eliten S. 676; zur Familie: Augsburger Stadtlexikon S. 746). Seit dem 17. Jh. befand sich die Hs in der Bibliothek von {\field{\*\fldinst HYPERLINK "hida://bezsoz[1].4600/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17\cf1 St. Ulrich und Afra}}\plain \f1\lang1033\fs22\cf1  ({\field{\*\fldinst HYPERLINK "hida://5650[0]/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17\cf1 Besitzvermerk}}\plain \f1\lang1033\fs22\cf1  1\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 : \plain \f1\i\lang1033\fs22\cf1 P.P Benedictinorum Imperialis Monasterii ss. Udalrici et Afrae Augustae 1658\plain \f1\lang1033\fs22\cf1 ).}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Arial;}{\f2\fnil\fcharset161 Arial;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

