\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22\cf1 105\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 -110\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs22\chcbpat17\cf1 Passionsgebete}}\plain \f1\lang1033\fs22\cf1  (Abla\u223 \'df jeweils durchgestrichen). \u8250 \'9b\plain \f1\i\lang1033\fs22\cf1 Wer dis nachgeschriben gebett spricht der wirt nit verdampt und hat gross aplas wenn man vnssern herren hebt\plain \f1\lang1033\fs22\cf1 \u8249 \'8b {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17\cf1 O ewiger gott herr Ihesus Cristus, lob und danck sy dir}}\plain \f1\i\lang1033\fs22\cf1  in ewigkait diner menschwerdung \plain \f1\lang1033\fs22\cf1 \u8230 \'85, (105\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1 ) \u8250 \'9b\u8230 \'85 \plain \f1\i\lang1033\fs22\cf1 sant Calixtus der hailig babst der hat gesetzt\plain \f1\lang1033\fs22\cf1  \u8230 \'85 \plain \f1\i\lang1033\fs22\cf1 disen nach geschribnen aplas\plain \f1\lang1033\fs22\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs22\cf1 Ach herr ich ermanen dich\plain \f1\lang1033\fs22\cf1  \plain \f1\i\lang1033\fs22\cf1 der ersamen fr\u246 \'f6d \plain \f1\lang1033\fs22\cf1 \u8230 \'85, (106\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs22\cf1 Wer dis nach geschriben pett spricht\plain \f1\lang1033\fs22\cf1  \u8230 \'85 \plain \f1\i\lang1033\fs22\cf1 hat aplas\plain \f1\lang1033\fs22\cf1  \u8230 \'85 (107\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 ) \plain \f1\i\lang1033\fs22\cf1 von dem hailgen babst sant Petern\plain \f1\lang1033\fs22\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs22\cf1 Bis wilkomen hail der welt,wort des vatters gewares opffer lebendigs flaisch\plain \f1\lang1033\fs22\cf1  \u8230 \'85, (108\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs22\cf1 Wer dis nach geschriben bett spricht\plain \f1\lang1033\fs22\cf1  \u8230 \'85 \plain \f1\i\lang1033\fs22\cf1 erlangt so vil tag ablas als vil wunden vnser Herr Cristus hat erlangt\plain \f1\lang1033\fs22\cf1  \u8230 \'85 \plain \f1\i\lang1033\fs22\cf1 den verlicht der babst Benedictus der sibent\plain \f1\lang1033\fs22\cf1  \u8230 \'85\u8249 \'8b \plain \f1\i\lang1033\fs22\cf1 O du aller liepster herr Ihesu Criste, ich bitt dich durch der \u250 \'fabertreffenlichen liebe willen \plain \f1\lang1033\fs22\cf1 \u8230 \'85 vgl. M\u252 \'fcnchen UB {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17\cf1 8\u176 \'b0 Cod. MS. 269}}\plain \f1\lang1033\fs22\cf1 ,20\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1 ; zur \u220 \'dcberlieferung s. M\u252 \'fcnchen UB {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17\cf1 4\u176 \'b0 Cod. MS. 489}}\plain \f1\lang1033\fs22\cf1 ,118\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1 .\plain \f1\i\lang1033\fs22\cf1  \plain \f2\lang1032\fs22\cf1 \u8213 \'af 108\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1  leer.}

