\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22\cf1 203\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 -221\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs22\chcbpat17\cf1 Mariengebete u. -exempla}}\plain \f1\lang1033\fs22\cf1  \u8250 \'9b\plain \f1\i\lang1033\fs22\cf1 Wer dis gebett spricht vnser lieben frowen dryssig tag\plain \f1\lang1033\fs22\cf1  \u8230 \'85 \plain \f1\i\lang1033\fs22\cf1 der wirt gentzlich gewert was er bitt\plain \f1\lang1033\fs22\cf1  \u8230 \'85\u8249 \'8b {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17\cf1 Sancta Maria ain junckfrow ob allen iunckfrowen ain m\u367 utter aller wirdigkait \u8230 \'85 Ich bitt dich}}\plain \f1\i\lang1033\fs22\cf1  durch das schnydent schwert \plain \f1\lang1033\fs22\cf1 \u8230 \'85 Vgl. \plain \f1\scaps\lang1033\fs22\cf1 Klapper\plain \f1\lang1033\fs22\cf1  4 S. 335-343; GW 12988 Bl CXVII\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1 -CXXV\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1 , (209\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 ) \plain \f1\i\lang1033\fs22\cf1 O du ku\u250 \'fasche junckfrow Maria ain tr\u246 \'f6sterin aller betr\u252 \'fcpten menschen, in dine hailgen hend empfilch ich dir min arme sel\plain \f1\lang1033\fs22\cf1  \u8230 \'85 GW 12988 Bl LXVII\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1 -LXIX\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 , (211\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 ) \plain \f1\i\lang1033\fs22\cf1 F\u252 \'fcrstine der hailgen, Ich ermanen dich der fr\u246 \'f6den die din m\u228 \'e4gtlichs hertz empfieng do dir der engel Gabriel kundt thett\plain \f1\lang1033\fs22\cf1  \u8230 \'85, (214\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 ) \plain \f1\i\lang1033\fs22\cf1 Gott gr\u252 \'fc\u223 \'df dich Maria m\plain \f3\i\lang1024\fs22\cf1 \u367 \'f9\plain \f1\i\lang1033\fs22\cf1 tter des allmechtigen gottes sun, erbarm dich \u250 \'faber mich, bitt f\u252 \'fcr mich dinen aller liepsten sun\plain \f1\lang1033\fs22\cf1  \u8230 \'85, (215\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1 ) \plain \f1\i\lang1033\fs22\cf1 Ain k\u250 \'fanigin aller engel und hailge gesegnete m\plain \f3\i\lang1024\fs22\cf1 \u367 \'f9\plain \f1\i\lang1033\fs22\cf1 tter gottes \u8230 \'85 erloub mir dich noch h\u250 \'fatt ze loben, wann ich arme s\u252 \'fcnderin wol erkenne\plain \f1\lang1033\fs22\cf1  \u8230 \'85, (222\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 ) Exempel: \plain \f1\i\lang1033\fs22\cf1 Es was ain g\plain \f3\i\lang1024\fs22\cf1 \u367 \'f9\plain \f1\i\lang1033\fs22\cf1 ter priester, der bettet dis gebet unser frowen alltag und do er an sinem end lag do erschain im unser frow\plain \f1\lang1033\fs22\cf1  \u8230 \'85 }

