\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22\cf1 226\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 -267\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs22\chcbpat17\cf1 Biblische Gleichnisse}}\plain \f1\lang1033\fs22\cf1  \u8250 \'9b\plain \f1\i\lang1033\fs22\cf1 Das ewangelium als Ihesus ain u\u223 \'df setzigen rain macht\plain \f1\lang1033\fs22\cf1 \u8249 \'8b\plain \f1\i\lang1033\fs22\cf1  \u8230 \'85 \plain \f1\lang1033\fs22\cf1 Mt 8,1-3, (227\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1 ) \u8250 \'9b\u8230 \'85 \plain \f1\i\lang1033\fs22\cf1 vom centurio\plain \f1\lang1033\fs22\cf1 \u8249 \'8b Mt 8,5-8, (230\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1 ) \u8250 \'9b\u8230 \'85\plain \f1\i\lang1033\fs22\cf1  von dem g\plain \f3\i\lang1024\fs22\cf1 \u367 \'f9ten \plain \f1\i\lang1033\fs22\cf1 somen und dem unkrut\plain \f1\lang1033\fs22\cf1 \u8249 \'8b Mt 13,27, (235\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 ) \u8250 \'9b\u8230 \'85 \plain \f1\i\lang1033\fs22\cf1 von dem plinden\plain \f1\lang1033\fs22\cf1 \u8249 \'8b Lc 18,31-43, (238\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1 ) \u8250 \'9b\u8230 \'85 \plain \f1\i\lang1033\fs22\cf1 von dem haydischen fr\u246 \'f6wlin\plain \f1\lang1033\fs22\cf1 \u8249 \'8b Mt 15,21-28, (245\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1 ) \u8250 \'9b\u8230 \'85 \plain \f1\i\lang1033\fs22\cf1 von dem ebr\u250 \'fachigen fr\u246 \'f6wlin\plain \f1\lang1033\fs22\cf1 \u8249 \'8b Io 8,2-11, (251\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 ) \u8250 \'9b\u8230 \'85 \plain \f1\i\lang1033\fs22\cf1 von dem haidische fr\u246 \'f6wlin ob den brunnen\plain \f1\lang1033\fs22\cf1 \u8249 \'8b Io 4,5-15, (255\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 ) \u8250 \'9b\u8230 \'85 \plain \f1\i\lang1033\fs22\cf1 von Zacheo\plain \f1\lang1033\fs22\cf1 \u8249 \'8b Lc 19,1-10, (259\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 ) \u8250 \'9b\u8230 \'85 \plain \f1\i\lang1033\fs22\cf1 von dem verloren sun\plain \f1\lang1033\fs22\cf1 \u8249 \'8b Lc 15,11-32.}

