\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://bezwrk[4].6930/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17\cf1 }}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22\cf1 (2\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 ) \plain \f1\i\lang1033\fs22\cf1 Modus processionum quarundam tempore tribulationum publice habendarum, ex sacerdotali Romano descriptus\plain \f1\lang1033\fs22\cf1 , (6\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 ) \plain \f1\i\lang1033\fs22\cf1 De processione habenda tempore pestis vel mortalitatis pecorum aut equorum\plain \f1\lang1033\fs22\cf1 , (19\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 ) \plain \f1\i\lang1033\fs22\cf1 Compendiolum aureum continens modum et rationem processionis tempore infectionis et mortalitatis pecorum\plain \f1\lang1033\fs22\cf1  \u8230 \'85 \plain \f1\i\lang1033\fs22\cf1 ex sacerdotali Romano\plain \f1\lang1033\fs22\cf1  \u8230 \'85 \plain \f1\i\lang1033\fs22\cf1 desumptum\plain \f1\lang1033\fs22\cf1  \u8230 \'85 {\field{\*\fldinst HYPERLINK "hida://5650[0].5686/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17\cf1 per Joannem Stecherum plebanum Luteraci indignum Anno domini 1599}}\plain \f1\lang1033\fs22\cf1 , lat. u. dt., (55\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 ) Vierzigst\u252 \'fcndiges Gebet: \plain \f1\i\lang1033\fs22\cf1 Horae et aliae orationes; laetaniae \plain \f1\lang1033\fs22\cf1 (!)\plain \f1\i\lang1033\fs22\cf1 , psalmi et preces ad usum horarum quadraginta, tempore belli Turcici compositae collectae et conscriptae per Joannem Stecherum\plain \f1\lang1033\fs22\cf1  \u8230 \'85 \plain \f1\i\lang1033\fs22\cf1 plebanum Luteraci indignum Anno salutis 1596\plain \f1\lang1033\fs22\cf1 , (112\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 ) \plain \f1\i\lang1033\fs22\cf1 Proce\u223 \'df und ordnung wie und mit welchen gepetten auch ceremonien der gro\u223 \'df Bettag wider den T\u252 \'fcrcken dar im 1594. Jar im Bistumb Constantz auf den 3. Novembris am ersten mal zuo verrichten ein gesetzt \u8230 \'85 in ma\u223 \'dfen der zuo Lauterach an der Yller angeordnet und gehalten ist worden, {\field{\*\fldinst HYPERLINK "hida://5650[1].5686/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17\cf1 beschriben durch Joannem Stecher unw\u252 \'fcrdig pfarrern daselbsten im 1594}}\plain \f1\i\lang1033\fs22\cf1 . Jar \plain \f1\lang1033\fs22\cf1  \u8230 \'85 darin (125\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 ) enthalten: \plain \f1\i\lang1033\fs22\cf1 Andechtiges gepett wider den grausamen Erbfeind den T\u252 \'fcrcken \u8230 \'85 welches \u8230 \'85 Herr Andreas Cardinal von \u214 \'d6sterreich, Bischoff zu Constantz und Brixen \u8230 \'85 zur Verrichtung \u8230 \'85 haben bevolhen,\plain \f1\lang1033\fs22\cf1  (170\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1 ) {\field{\*\fldinst HYPERLINK "hida://5650[2].5686/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17\cf1 Finit faeliciter Anno 1596 pridie Idus novembris}}\plain \f1\lang1033\fs22\cf1  (12. Nov. 1596)\plain \f2\lang1032\fs22\cf1 . \u8213 \'af \plain \f1\lang1033\fs22\cf1 Der Schreiber/ Kompilator ist m\u246 \'f6glicherweise identisch mit dem 1585 an der Universit\u228 \'e4t Dillingen immatrikulierten {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100gi/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17\cf1 Johannes Stecher}}\plain \f1\lang1033\fs22\cf1  (s. Matrikel Dillingen 1, S. 158 Nr. 91).}

