\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22\cf1 48\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 -74\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs22\chcbpat17\cf1 Ordo missae iuxta consuetudinem romanae ecclesiae}}\plain \f1\lang1033\fs22\cf1  \u8250 \'9b\plain \f1\i\lang1033\fs22\cf1 Incipit ordo agendorum et dicendorum a sacerdote in missa iuxta consuetudinem Romane ecclesie. Et  in primis quando preparat se sacerdos ad celebrandum missam dicat hos psalmos\plain \f1\lang1033\fs22\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs22\cf1 Quam dilecta\plain \f1\lang1033\fs22\cf1 . \u8250 \'9b\plain \f1\i\lang1033\fs22\cf1 Psalmus\plain \f1\lang1033\fs22\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs22\cf1 Benedixisti ...-... et per te cepta finiatur per Christum dominum nostrum etc\plain \f1\lang1033\fs22\cf1 . \u8250 \'9b\plain \f1\i\lang1033\fs22\cf1 Et sic est finis\plain \f1\lang1033\fs22\cf1 \u8249 \'8b.}

