\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22\cf1 \u8250 \'9b\plain \f1\i\lang1033\fs22\cf1 Psalterium BMV \u8230 \'85\plain \f1\lang1033\fs22\cf1 \u8249 \'8b AH 35 Nr. XV, (103\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs22\cf1 Oratio super ave Maria\plain \f1\lang1033\fs22\cf1  \u8230 \'85\u8249 \'8b  AH 30 Nr. 150, (105\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs22\cf1 Letania de beata virgine\plain \f1\lang1033\fs22\cf1 \u8249 \'8b mit Collecta, (106\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1 ) AH 9 Nr. 82, (107\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 ) \plain \f1\i\lang1033\fs22\cf1 Gaude virgo speciosa, mater dei gloriosa\plain \f1\lang1033\fs22\cf1  \u8230 \'85 20 Strophen, nur einzelne Verse \u252 \'fcbereinstimmend mit anderen Reimgebeten (AH 50 Nr. 370, AH 32 Nr. 21. 63), (108\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 ) AH 30 Nr. 105, (108\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1 ) AH 54 Nr. 247, (109\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 ) AH 38 Anhang, S. 243 Nr. 2. AH 20 Nr. 11, (110\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 ) {\field{\*\fldinst HYPERLINK "hida://5650[15].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17\cf1 Singularis meriti sola sine exemplo mater et virgo}}\plain \f1\i\lang1033\fs22\cf1  \plain \f1\lang1033\fs22\cf1 \u8230 \'85 Nur Anfang identisch mit PL 101,1400, (111\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1 ) {\field{\*\fldinst HYPERLINK "hida://5650[12].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17\cf1 O sancta et beatissima virgo Maria, Theotocos theotoca}}\plain \f1\lang1033\fs22\cf1  \u8230 \'85, (112\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1 ) {\field{\*\fldinst HYPERLINK "hida://5650[10].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17\cf1 O Maria mater dei, ad te refugimus}}\plain \f1\i\lang1033\fs22\cf1  rei cum magna fiducia\plain \f1\lang1033\fs22\cf1  \u8230 \'85, (113\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs22\cf1 Oratio ad dominum Ihesum \u8230 \'85\plain \f1\lang1033\fs22\cf1 \u8249 \'8b Ausz\u252 \'fcge aus AH 38 Nr. 6 Str. 22.137-139. 143. 125. 111. 96, (113\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs22\cf1 alia oratio\plain \f1\lang1033\fs22\cf1 \u8249 \'8b AH 38 Nr. 6 Str. 13. 15. 24. 89. 54. 82. 62, (113\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1 ) {\field{\*\fldinst HYPERLINK "hida://5650[7].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17\cf1 Dulcissime domine Ihesu Christe, ob tui coporis reverenciam}}\plain \f1\lang1033\fs22\cf1  \u8230 \'85 5 \lquote dulcissime\rquote  Gebete, hier Hugo de s. Victore zugeschrieben, (114\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs22\cf1 Oratio ad dominum Ihesum Christum et valde solennis\plain \f1\lang1033\fs22\cf1 \u8249 \'8b \plain \f1\scaps\lang1033\fs22\cf1 Schaller/\plain \f1\scaps\lang1033\fs22\cf1  \plain \f1\scaps\lang1033\fs22\cf1 K\plain \f1\scaps\lang1033\fs22\cf1 \u246 \'f6\plain \f1\scaps\lang1033\fs22\cf1 nsgen\plain \f1\lang1033\fs22\cf1 , Nr. 8579, (114\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs22\cf1 Oratio \u8230 \'85 valde utilis\plain \f1\lang1033\fs22\cf1 \u8249 \'8b AH 31 Nr. 32 (mit Auslassungen), (115\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 ) AH 30 Nr. 127, (115\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1 ) AH 32 Nr. 31. 57, (116\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1 ) {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17\cf1 Ave mundi domina, stella maris Maria, ave dulcis viola}}\plain \f1\lang1033\fs22\cf1  \u8230 \'85 \u228 \'e4hnlich \plain \f1\scaps\lang1033\fs22\cf1 Chevalier\plain \f1\lang1033\fs22\cf1  Nr. 1968, \plain \f1\i\lang1033\fs22\cf1 Ave Maria porta paradisi stella mundi destructio inferni\plain \f1\lang1033\fs22\cf1  \u8230 \'85 \plain \f1\scaps\lang1033\fs22\cf1 Stegm\plain \f1\scaps\lang1033\fs22\cf1 \u252 \'fc\plain \f1\scaps\lang1033\fs22\cf1 ller\plain \f1\lang1033\fs22\cf1  RB 6,8525, (117\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 ) {\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17\cf1 Domine Ihesu Christe, fili dei vivi, qui pro nobis nasci voluisti, ut nos ab eterna morte liberares}}\plain \f1\lang1033\fs22\cf1  \u8230 \'85 \u228 \'e4hnlich Hildesheim Dombibl. {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17\cf1 Hs 735}}\plain \f1\lang1033\fs22\cf1 ,95\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1 , (118\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs22\cf1 Quicumque devote dixerit hanc oracionem concessit Ioh. papa 20 centum dies\plain \f1\lang1033\fs22\cf1  \u8230 \'85\u8249 \'8b AH 6 Nr. 21 (leicht variierend), (119\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs22\cf1 Meditatio domini Bonaventure super ave Maria\plain \f1\lang1033\fs22\cf1  \u8230 \'85\u8249 \'8b {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17\cf1 Ave Maria gratia plena dominus tecum. Tibi domine deus gracias quas possum refero}}\plain \f1\i\lang1033\fs22\cf1  ex intimis precordiis meis\plain \f1\lang1033\fs22\cf1  \u8230 \'85-\u8230 \'85 \plain \f1\i\lang1033\fs22\cf1 recogitans que sunt matris et filii. Amen.\plain \f1\lang1033\fs22\cf1  Verfasserschaft zweifelhaft vgl. \plain \f1\scaps\lang1033\fs22\cf1 Distelbrink\plain \f1\lang1033\fs22\cf1 , Bonaventurae scripta S. 155, (122\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs22\cf1 Quinque gaudia beati Berenardi (!) abbatis\plain \f1\lang1033\fs22\cf1  \plain \f4\lang1024\fs22\cf1 [\plain \f1\lang1033\fs22\cf1 Claraevallensis\plain \f4\lang1024\fs22\cf1 ]\plain \f1\lang1033\fs22\cf1  \plain \f1\i\lang1033\fs22\cf1 ad beatissimam virginem Mariam\plain \f1\lang1033\fs22\cf1 \u8249 \'8b {\field{\*\fldinst HYPERLINK "hida://5650[9].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17\cf1 O gloriosa virgo Maria, quam ineffabilem gratiam apud deum meruisti}}\plain \f1\lang1033\fs22\cf1  \u8230 \'85, (124\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 ) 2 kurze Mariengebete, (124\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs22\cf1 Gaudia Mariae virginis\plain \f1\lang1033\fs22\cf1 \u8230 \'85\u8249 \'8b AH 31 Nr. 181 (mit Varianten der Hs D), (125\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 ) Anselmus \plain \f4\lang1024\fs22\cf1 [\plain \f1\lang1033\fs22\cf1 Cantuariensis\plain \f4\lang1024\fs22\cf1 ]\plain \f1\lang1033\fs22\cf1 : Oratio XX ad Christum PL 158,902, (127\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 ) Urbanus papa V.: Oratio de corpore Christi {\field{\*\fldinst HYPERLINK "hida://5650[13].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17\cf1 O verbum incarnatum atque misterium domini nostri Ihesu Christi, o salus et vita}}\plain \f1\i\lang1033\fs22\cf1 , o pax et caritas\plain \f1\lang1033\fs22\cf1  \u8230 \'85, Antiphonen und Gebet: \plain \f1\i\lang1033\fs22\cf1 Domine Ihesu Christe qui in ultima cena tua tradidisti\plain \f1\lang1033\fs22\cf1  \u8230 \'85, (128\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs22\cf1 Psalterium de salvatore