\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22\cf1 186\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 -202\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs22\chcbpat17\cf1 Orationes et rosarium BMV}}\plain \f1\lang1033\fs22\cf1  \u8250 \'9b\plain \f1\i\lang1033\fs22\cf1 Secuntur orationes primo de totali statu et vita beate Marie virginis\plain \f1\lang1033\fs22\cf1 \u8249 \'8b {\field{\*\fldinst HYPERLINK "hida://5650[12].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17\cf1 Salve Maria dei genitrix, virgo, mater misericordie, redemptrix humani generis, cuius singularis precellencia}}\plain \f1\lang1033\fs22\cf1  \u8230 \'85, (187\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs22\cf1 Incipit oratio super ewangelicam salutacionem\plain \f1\lang1033\fs22\cf1 \u8249 \'8b {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17\cf1 Ave Maria gratia plena dominus tecum. Vere dominus tecumque tibi dedit}}\plain \f1\i\lang1033\fs22\cf1 , ut omnis natura tm? adorare te deberet, obsecro te\plain \f1\lang1033\fs22\cf1  \u8230 \'85, (188\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1 ) AH 30 Nr. 100, (188\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs22\cf1 De quinque festis beate Marie\plain \f1\lang1033\fs22\cf1 \u8249 \'8b {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17\cf1 Ave cuius conceptio, solennis plena gaudio}}\plain \f1\lang1033\fs22\cf1  \u8230 \'85 \plain \f1\scaps\lang1033\fs22\cf1 Chevalier\plain \f1\lang1033\fs22\cf1  Nr. 1744\plain \f2\lang1033\fs20\cf1 , \plain \f1\lang1033\fs22\cf1 (188\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1 ) CO 1875, (189\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs22\cf1 Incipit Rosarium beate Marie virginis\plain \f1\lang1033\fs22\cf1 \u8249 \'8b {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17\cf1 Ave Maria \u8230 \'85 Ihesus Christus quem de spiritu sancto angelo Gabriele nunciante concepisti}}\plain \f1\lang1033\fs22\cf1  \u8230 \'85 51 Strophen, mit keiner der bei \plain \f1\scaps\lang1033\fs22\cf1 K.J. Klinkhammer\plain \f1\lang1033\fs22\cf1 , Adolf von Essen und seine Werke, Frankfurt/M. 1972, abgedruckten Fassungen identisch, am \u228 \'e4hnlichsten dem \u8218 \'825. Rosarium\rquote  S. 238-240, (191\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 ) {\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17\cf1 Deus, qui privilegium tocius gracie et divini amoris}}\plain \f1\lang1033\fs22\cf1  \u8230 \'85 Parallel\u252 \'fcberlieferung: Hildesheim DomB {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17\cf1 J 30}}\plain \f1\lang1033\fs22\cf1 ,75\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 , (191\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs22\cf1 De gaudiis BMV oratio preclara ad quam devote dicentibus Johannes papa 22\plain \f1\i\super\lang1033\fs24\cf1 us\plain \f1\i\lang1033\fs22\cf1  dedit tria milia dierum indulgentiarum\plain \f1\lang1033\fs22\cf1 \u8249 \'8b {\field{\*\fldinst HYPERLINK "hida://5650[13].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17\cf1 Salve mater speciosa, iam in celis gloriosa}}\plain \f1\lang1033\fs22\cf1  \u8230 \'85 AH 30 Nr. 115, \plain \f1\scaps\lang1033\fs22\cf1 Chevalier\plain \f1\lang1033\fs22\cf1  Nr. 18052, (192\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 ) {\field{\*\fldinst HYPERLINK "hida://5650[18].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17\cf1 Te matrem dei laudamus, te Mariam virginem confitemur}}\plain \f1\lang1033\fs22\cf1  \u8230 \'85\plain \f1\scaps\lang1033\fs22\cf1  \plain \f1\lang1033\fs22\cf1 \u228 \'e4hnlich \plain \f1\scaps\lang1033\fs22\cf1 Chevalier\plain \f1\b\lang1033\fs22\cf1  \plain \f1\lang1033\fs22\cf1 Nr. 20158, (193\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1 ) {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17\cf1 Deus qui gloriosam virginem Mariam laudibus inenarrabilibus honorasti }}\plain \f1\lang1033\fs22\cf1 \u8230 \'85, (193\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs22\cf1 Oratio super Salve regina\plain \f1\lang1033\fs22\cf1 \u8249 \'8b {\field{\*\fldinst HYPERLINK "hida://5650[14].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17\cf1 Salve virgo virginum stella matutina, sordidorum criminum }}\plain \f1\lang1033\fs22\cf1 \u8230 \'85 \plain \f1\scaps\lang1033\fs22\cf1 Chevalier\plain \f1\lang1033\fs22\cf1  Nr. 18318, (195\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1 ) {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17\cf1 Deus qui maiestatis tue speculum angelorum solacium nostre salutis}}\plain \f1\lang1033\fs22\cf1  \u8230 \'85 vgl. Hildesheim DomB {\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17\cf1 J 30}}\plain \f1\lang1033\fs22\cf1 ,44\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 , (195\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs22\cf1 Bonifacius papa octavus composuit sequencia metra super salve regina et XL dies indulgenciarum eam devote dicentibus\plain \f1\lang1033\fs22\cf1 \u8249 \'8b AH 32 Nr. 141, ab Z. 11 abweichend, (196\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs22\cf1 Salutatio omnium membrorum beate Marie virginis\plain \f1\lang1033\fs22\cf1 \u8249 \'8b {\field{\*\fldinst HYPERLINK "hida://5650[17].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17\cf1 Suscipe genitrix dei eterni omnipotentis regis obsequia humilis servi tui}}\plain \f1\i\lang1033\fs22\cf1  et indignas laudes\plain \f1\lang1033\fs22\cf1  \u8230 \'85, (198\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs22\cf1 Oratio ante altare vel ante ymaginem beatissime Marie virginis\plain \f1\lang1033\fs22\cf1 \u8249 \'8b {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17\cf1 Desiderantissima miseratrix et porta peccatorum}}\plain \f1\i\lang1033\fs22\cf1 , salus et spes omnium in te sperancium \u8230 \'85 ante altare nomini tuo dedicatum preces fundo in conspectu reliquiarum tuarum\plain \f1\lang1033\fs22\cf1  \u8230 \'85, (199\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs22\cf1 Oratio beati Bernhardi ad virginem Mariam\plain \f1\lang1033\fs22\cf1 \u8249 \'8b {\field{\*\fldinst HYPERLINK "hida://5650[7].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17\cf1 Memento obsecro dulcis mater et domina}}\plain \f1\lang1033\fs22\cf1  \u8230 \'85 vgl. \plain \f1\scaps\lang1033\fs22\cf1 Haimerl\plain \f1\b\lang1033\fs22\cf1  \plain \f1\lang1033\fs22\cf1 S.182, {\field{\*\fldinst HYPERLINK "hida://5650[15].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17\cf1 Sancta Maria mater domini nostri Ihesu Christi pia et perpetua virgo, maris stella porta paradisi, ego indignus peccator confugio sub tuam protectionem}}\plain \f1\i\lang1033\fs22\cf1  \plain \f1\lang1033\fs22\cf1 \u8230 \'85, (200\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs22\cf1 pro reconciliacione peccatoris oratio\plain \f1\lang1033\fs22\cf1 \u8249 \'8b {\field{\*\fldinst HYPERLINK "hida://5650[9].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17\cf1 O Maria mater dei, mater misericordie \u8230 \'85 Scio quod in te et filium tuum gravissime peccavi}}{\field{\*\fldinst HYPERLINK "hida://5650[9].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17\cf1  }}\plain \f1\lang1033\fs22\cf1 \u8230 \'85, (201\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs22\cf1 Oratio de Sancta Maria pro vivis et defunctis\plain \f1\lang1033\fs22\cf1 \u8249 \'8b {\field{\*\fldinst HYPERLINK "hida://5650[8].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17\cf1 O domina mundi misericordissima, dei genitrix, virgo perpetua, dignare meis indignis convertere precibus}}\plain \f1\lang1033\fs22\cf1  \u8230 \'85, (201\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs22\cf1 Sancta Maria in omni adversitate et necessitate\plain \f1\lang1033\fs22\cf1 \u8249 \'8b {\field{\*\fldinst HYPERLINK "hida://5650[16].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17\cf1 Sanctissima mater dei genitrix gloriosa virgo \u8230 \'85 Surge cum omni milicia celestis exercitus}}\plain \f1\lang1033\fs22\cf1  \u8230 \'85, (201\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs22\cf1 Oratio de s. Maria\plain \f1\lang1033\fs22\cf1 \u8249 \'8b AH 49 Nr. 656, (202\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 ) {\field{\*\fldinst HYPERLINK "hida://5650[11].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17\cf1 O sancta Maria virgo virginum, mater et filia regis regum omnium, tuum nobis impende solacium}}\plain \f1\lang1033\fs22\cf1  \u8230 \'85 vgl. Vatikan BA {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17\cf1 Reg. lat 165,44}}\plain \f1\lang1033\fs22\cf1  (\plain \f1\scaps\lang1033\fs22\cf1 Wilmart\plain \f1\lang1033\fs22\cf1 ), (202\plain \f1\super\lang1033\fs