\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22\cf1 202\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1 -207\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1  {\field{\*\fldinst HYPERLINK "hida://bezwrk[3].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs22\chcbpat17\cf1 Orationes et hymni de angelis, sanctis, patriarchis, apostolis, virginibus, patronis}}\plain \f1\lang1033\fs22\cf1  \plain \f1\i\lang1033\fs22\cf1 Summi regis archangele Michael, intende queso meis peccatis\plain \f1\lang1033\fs22\cf1  \u8230 \'85 \plain \f1\scaps\lang1033\fs22\cf1 Chevalier\plain \f1\lang1033\fs22\cf1  Nr. 19734 f., \plain \f1\scaps\lang1033\fs22\cf1 Schaller/K\plain \f1\scaps\lang1033\fs22\cf1 \u246 \'f6\plain \f1\scaps\lang1033\fs22\cf1 nsgen\plain \f1\lang1033\fs22\cf1  Nr. 15830, (203\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1 ) {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17\cf1 Deus omnium conditor et redemptor, qui per sanctos angelos tuos potenciam tuam}}\plain \f1\lang1033\fs22\cf1  \u8230 \'85, {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17\cf1 Benigne Angele, qui miles invictissimi et eterni regis vocari dignatus es}}\plain \f1\lang1033\fs22\cf1  \u8230 \'85, (204\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 ) {\field{\*\fldinst HYPERLINK "hida://5650[9].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17\cf1 Omnipotens sempiterne deus, qui angelum sanctum antequam nascerer}}\plain \f1\i\lang1033\fs22\cf1  mihi ad custodiendum predestinasti\plain \f1\lang1033\fs22\cf1  \u8230 \'85, {\field{\*\fldinst HYPERLINK "hida://5650[12].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17\cf1 Sancte Johannes baptista, preco eterni iudicis, o Johannes maior}}\plain \f1\i\lang1033\fs22\cf1  \plain \f1\lang1033\fs22\cf1 \u8230 \'85, (204\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1 ) {\field{\*\fldinst HYPERLINK "hida://5650[11].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17\cf1 Sancte Johannes Baptista electe dei qui precursor dei extitisti }}\plain \f1\lang1033\fs22\cf1 \u8230 \'85, {\field{\*\fldinst HYPERLINK "hida://5650[7].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17\cf1 Nobilissime radices patriarche et prophete et omnes iusti ante adventum deo grati}}\plain \f1\i\lang1033\fs22\cf1 , qui diem desiderastis\plain \f1\lang1033\fs22\cf1  \u8230 \'85, (205\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 ) AH 15 Nr. 138, (205\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1 ) {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17\cf1 Gloriosissimi principes apostoli et ewangeliste, omnesque discipuli domini}}\plain \f1\i\lang1033\fs22\cf1  \plain \f1\lang1033\fs22\cf1 \u8230 \'85, (206\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 ) {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17\cf1 Gloriosissime salvatoris nostri apostole, patrone illustrissime sancte N. apostole meus electissime}}\plain \f1\lang1033\fs22\cf1  \u8230 \'85, (206\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1 ) {\field{\*\fldinst HYPERLINK "hida://5650[8].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17\cf1 O invictissimi et constantissimi dei milites et Christi martires}}\plain \f1\i\lang1033\fs22\cf1  splendidissimi \u8230 \'85 qui oblectamenta male blandientis seculi despexistis\plain \f1\lang1033\fs22\cf1  \u8230 \'85, {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17\cf1 Dignissimi et preclarissimi sancti pontifices et confessores Christi}}\plain \f1\i\lang1033\fs22\cf1 , doctores egregii\plain \f1\lang1033\fs22\cf1  \u8230 \'85, {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17\cf1 Felicissime et castissime virgines, cordis corporis et operis mundicia}}\plain \f1\lang1033\fs22\cf1  \u8230 \'85, (207\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 ) {\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17\cf1 Ihesu premium regnancium et ductor viatorum, salva nos}}\plain \f1\lang1033\fs22\cf1  \u8230 \'85 nur Anfang wie AH 28 Nr. 41 (Z.1-10), {\field{\*\fldinst HYPERLINK "hida://5650[10].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17\cf1 Sancte domine care et noster patrone singularis, noli me despicere peccatorem}}\plain \f1\lang1033\fs22\cf1  \u8230 \'85, {\field{\*\fldinst HYPERLINK "hida://5650[13].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17\cf1 Sancti et sancte dei omnes quorum hodie currit dies natalis in toto orbe terrarum}}\plain \f1\lang1033\fs22\cf1  \u8230 \'85}

