\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22\cf1 \u8250 \'9b\plain \f1\i\lang1033\fs22\cf1 Quomodo homo quottidie se disponat ad mortem\plain \f1\lang1033\fs22\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs22\cf1 Ego frater Georius confiteor tibi omnipotens clementissime deus pater multitudinem et magnitudinem ac enormitatem universorum scelerum\plain \f1\lang1033\fs22\cf1  \u8230 \'85, (224\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs22\cf1 Commendacio anime sui ipsius\plain \f1\lang1033\fs22\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs22\cf1 Commendo te omnipotenti deo carissima anima mea\plain \f1\lang1033\fs22\cf1  \u8230 \'85 \plain \f1\scaps\lang1033\fs22\cf1 van Dijk\plain \f1\lang1033\fs22\cf1 , Sources of the Modern Roman Liturgy S. 392, (225\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs22\cf1 Allocucio anime\plain \f1\lang1033\fs22\cf1 \u8249 \'8b {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17\cf1 Proficiscere de hoc mundo in die vocacionis tue}}\plain \f1\lang1033\fs22\cf1  \u8230 \'85, (225\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs22\cf1 Oracio pro bono fine\plain \f1\lang1033\fs22\cf1 \u8249 \'8b {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17\cf1 Domine Ihesu Christe fili dei vivi, per amaritudinem passionis et mortis tue}}\plain \f1\lang1033\fs22\cf1  \u8230 \'85 (vgl. Soest StB {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17\cf1 Cod 15}}\plain \f1\lang1033\fs22\cf1 ,106\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1 ), (226\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs22\cf1 Ad sanctam Mariam\plain \f1\lang1033\fs22\cf1 \u8249 \'8b {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17\cf1 O Regina celorum mater misericordie confugium et refugium peccatorum}}\plain \f1\lang1033\fs22\cf1  \u8230 \'85 (vgl. Herzogenburg StiftsB {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17\cf1 Cod 85}}\plain \f1\lang1033\fs22\cf1 ,197\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 ), \u8250 \'9b\plain \f1\i\lang1033\fs22\cf1 Ad omnes sanctos\plain \f1\lang1033\fs22\cf1 \u8249 \'8b \plain \f1\i\lang1033\fs22\cf1 Succurrite mihi gloriosi principes\plain \f1\lang1033\fs22\cf1  \u8230 \'85, (226\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs22\cf1 ) \u8250 \'9b\plain \f1\i\lang1033\fs22\cf1 Forma absolucionis approbata in mortis articulo cum plenaria remissione\plain \f1\lang1033\fs22\cf1 \u8249 \'8b (2). }

