\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22\cf1 113\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 -115\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs22\chcbpat17\cf1 Mariengebet}}\plain \f1\lang1033\fs22\cf1  \u8250 \'9b\plain \f1\i\lang1033\fs22\cf1 Item aber ain g\u252 \'fct gebet von unser frowen\plain \f1\lang1033\fs22\cf1 \u8249 \'8b {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f3\i\lang1024\fs22\chcbpat17\cf1 Ach hailige k\u252 \'fcngin maget Maria und m\u367 \'f9ter unsers herren Ihesu Christi}}\plain \f3\i\lang1024\fs22\cf1 , ich armer sunder bitt dich durch die verk\u252 \'fcndung und entpfenkn\u252 \'fc\u223 \'df der menschait dines hailigen lieben s\u365 unes\plain \f1\lang1033\fs22\cf1  \u8230 \'85(115\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs22\cf1 ) \plain \f1\i\lang1033\fs22\cf1 und daz din hailigen und lieben engeln mich f\u252 \'fcren und laiten in daz \u246 \'f6wige leben Amen\plain \f1\lang1033\fs22\cf1 . }

